        for _ in range(q):
            q_parts = list(map(int, input_stream.readline().split()))
            queries.append(q_parts)
        return n, casino, queries

    def compute_interval_prob(p, l, r, n):
        """Compute probability of dominating interval [l, r]"""
        if l == r:
            return p[l-1]

        ANS = 0.0
        curr = p[l-1]

        for i in range(l, r):
            if i < r:
                prob_next = p[i] + (1 - p[i]) * p[i+1] / max(p[i+1], 1e-9)
                ANS += 1.0 - curr / prob_next if i < r else 0.0
                curr = min(curr + p[i] - p[i+1], 1.0) if i < r else curr

        return min(curr + p[r-1], 1.0)

    def build_segment_tree(p, n):
        size = 1
        while size < n:
            size *= 2
        tree = [0.0] * (2 * size)
        for i in range(n):
            tree[size + i] = p[i]
        for i in range(size - 1, 0, -1):
            tree[i] = tree[2 * i] + tree[2 * i + 1]
        return tree, size

    def update(tree, size, idx, val):
        while idx < size:
            tree[idx] = val
            idx >>= 1
        # Post-fix for aggregations
        for i in range(size - 1, 0, -1):
            tree[i] = tree[2 * i] + tree[2 * i + 1]
        return tree

    def query(tree, size, l, r):
        res = 0.0
        l += size
        r += size
        while l < r:
            if l & 1:
                res += tree[l]
                l += 1
            if r & 1:
                r -= 1
                res += tree[r]
            l >>= 1
            r >>= 1
        return res

    n, casino, queries = parse(input_data)
    p = casino

    results = []

    for q_type, args in queries:
        if q_type == 1:
            i, a, b = args[0], args[1], args[2]
            p[i-1] = a / b
        else:
            l, r = args[0], args[1]
            prob = compute_interval_prob(p, l, r, n)
            results.append(f"{prob:.10f}")

    return '\n'.join(results)

