def polynomial_mul(A, B, offset_A, offset_B):
    """Multiply two polynomials A and B, where A is represented as (coefficients, offset)."""
    n = len(A)
    m = len(B)
    new_len = n + m - 1

    new_offset = offset_A + offset_B
    new_poly = [0] * new_len

    for i in range(n):
        if A[i] == 0:
            continue
        for j in range(m):
            if B[j] == 0:
                continue
            new_poly[i + j] = (new_poly[i + j] + A[i] * B[j]) % MOD

    return tuple(new_poly), new_offset

