    """Count number of ways to get each possible sum after t turns."""
    if t == 0:
        count = poly_ops([(0,), 0])
        return [(1,), 0]

    # Binary exponentiation: poly^t
    def poly_pow(P, power):
        if power == 0:
            return (1,), 0  # Identity (x^0 with offset 0)
        if power == 1:
            return P
        result = (1,), 0
        base = P
        exp = power

        while exp > 0:
            if exp % 2 == 1:
