def solve_problem(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, _ = map(int, lines[0].split())
    events = lines[1:]

    # Get all unique friend names who visit
    visitor_names = set()
    for line in events:
        parts = line.split()
        if len(parts) >= 2 and parts[0] == '2':
            visitor_names.add(parts[1])

    if not visitor_names:
        return '0'

    # Sort for deterministic ordering
    ids = sorted(visitor_names)
    name_to_id = {name: i for i, name in enumerate(ids)}
    n_friends = len(ids)

    # Build periods (sequences between type-1 events)
    periods = []
    current = []

    for line in events:
        parts = line.split()
        if len(parts) == 0:
            continue
        if parts[0] == '1':
            if current:
                periods.append(tuple(current))
                current = []
        elif parts[0] == '2' and len(parts) >= 2:
            if parts[1] in name_to_id:
                current.append(name_to_id[parts[1]])

    if current:
        periods.append(tuple(current))

    # Build conflict masks: if friend i and j appear together in a period, they conflict
    conflict_mask = [0] * n_friends

    for period in periods:
        combined = 0
        for f in period:
            conflict_mask[f] |= combined
            combined |= (1 << f)

    # Maximum Independent Set using backtracking with pruning
    best = 0

    def backtrack(idx, count, skip_mask):
        nonlocal best

        # Pruning: can we possibly beat best?
        if count + (n_friends - idx) <= best:
            return

        if idx == n_friends:
            best = max(best, count)
            return

        # Option 1: Skip friend idx
        backtrack(idx + 1, count, skip_mask)

        # Option 2: Include friend idx (if not skipped)
        if (skip_mask >> idx) & 1 == 0:
            new_skip = skip_mask | conflict_mask[idx]
            backtrack(idx + 1, count + 1, new_skip)

    backtrack(0, 0, 0)
    return str(best)

def solution(input_str):
    return solve_problem(input_str)

