def is_stable(perm, n, costs):
    """Check if a matching is stable (no blocking pairs)"""
    partner = [0] * n
    for i, p in enumerate(perm):
        partner[i] = p

    for i in range(n):
        current_partner = partner[i]
        current_cost = costs[i][current_partner]

        # Check all other cities to see if any would be better
        for j in range(n):
            if j == i or j == current_partner:
                continue

            # Would i prefer j?
            if costs[i][j] < current_cost:
                # Would j also prefer i?
                j_partner = partner[j]
                if costs[j][i] < costs[j][j_partner]:
                    return False

    return True

def solve(n, costs):
    """Try to find a stable matching"""
    if n % 2 != 0:
        return -1

    # For small N, try all permutations
    import itertools

    def is_valid(perm):
        seen = set()
        for p in perm:
            seen.add(p)
        return len(seen) == n

    for perm in itertools.permutations(range(n)):
        if is_valid(perm):
            if is_stable(perm, n, costs):
                return ' '.join(map(str, perm))

    return -1

