MOD = 998244353

def power(a, b):
    """Compute a^b mod MOD"""
    res = 1
    a = a % MOD
    while b:
        if b % 2 == 1:
            res = res * a % MOD
        a = a * a % MOD
        b //= 2
    return res

def modinv(n):
    """Compute modular inverse using Fermat's little theorem"""
    return power(n, MOD - 2)

