def solution(input_str):
    # Handle empty or malformed input
    if not input_str or not input_str.strip():
        return "0\n"

    # Parse n and m
    try:
        line = input_str.split('\n')[0].strip()
        if not line:
            return "0\n"
        n, m = map(int, line.split())
    except:
        return "0\n"

    # Handle edge case
