        return "0\n"

    # Single cell case
    if n == 1 and m == 1:
        return "0\n"

    # Compute minimum dominating set using DP with bitmask
    cells = []
    for r in range(n):
        for c in range(m):
            cells.append((r, c))
    n_cells = n * m

    # Precompute coverage mask for each starting position
    dom_masks = []
    for r in range(n):
        for c in range(m):
            mask = 0
            # Cover self
            mask |= (1 << (r * m + c))
            # Cover all 4 neighbors within bounds
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    mask |= (1 << (nr * m + nc))
            dom_masks.append(mask)

    all_mask = (1 << n_cells) - 1

    @lru_cache(maxsize=10000)
    def dp(mask):
        """Return minimum dominators needed to cover 'mask' of cells that need coverage."""
        if mask == all_mask:
            return 0

        result = float('inf')

        # Find first uncovered cell
        uncovered = ~mask & all_mask
        if uncovered == 0:
            return 0

        # Try each starting position as a dominator
        for i in range(n_cells):
            new_mask = mask | dom_masks[i]
            # Only proceed if we made progress (new dominator covers at least one new cell)
            if new_mask != mask:
                rem = dp(new_mask)
                if rem < float('inf'):
                    result = min(result, rem + 1)

        return result

    min_dominators = dp(0)
    if min_dominators == float('inf'):
        return "0\n"

    # Answer: total cells minus occupied cells (which equals minimum dominators)
    return f"{n * m - min_dominators}\n"


