    k = list(map(int, lines[1].split()))
    k = [0] + k  # 1-indexed for convenience

    # Parse offers: store unique sale days per item type
    offers_by_type = {}
    for i in range(2, 2 + m):
        d, t = map(int, lines[i].split())
        if t not in offers_by_type:
            offers_by_type[t] = set()
        offers_by_type[t].add(d)

    # Sort sale days for binary search
    for t in offers_by_type:
        offers_by_type[t] = sorted(list(offers_by_type[t]))

    def check(X):
        """Check if Ivan can afford all transactions by day X"""
        total_cost = 0

        for t in range(1, n + 1):
            count = k[t]
            if count == 0:
                continue

            sale_days = offers_by_type.get(t, [])
            if not sale_days:
                # No sale option, must buy at regular price
                total_cost += count * 2
            else:
                # Find the latest sale day <= X
                idx = bisect.bisect_right(sale_days, X) - 1
                if idx >= 0:
                    total_cost += count  # 1 burle on sale
                else:
                    total_cost += count * 2  # 2 burles regular

        return total_cost <= X

    # Binary search for minimum days
    low = 1
    high = 1000000  # Upper bound: enough to cover all regular purchases
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(ans)

