    if end_mins <= start_mins:
        elapsed = h * m + (end_mins - start_mins)
    else:
        elapsed = end_mins - start_mins

    if elapsed <= 0 or elapsed >= h * m:
        return "0\n"

    count = 0
    cur_h, cur_m = h1, m1

    for _ in range(elapsed):
        next_m = cur_m + 1
        if next_m >= m:
            next_m = 0
            cur_h = (cur_h + 1) % h
        else:
