def solution(s):
    n, m = map(int, s.split())
    roots = set()
    for b in range(1, n + 1):
        min_c = 1
        max_c = min(m, b * b)
        for c in range(min_c, max_c + 1):
            k = b * b - c
            roots.add(-b - k ** 0.5)  # No, this needs precision
